func (s *Service) validateDataColumn(ctx context.Context, pid peer.ID, msg *pubsub.Message) (pubsub.ValidationResult, error) {
    // Always accept our own messages
    if pid == s.cfg.p2p.PeerID() { return pubsub.ValidationAccept, nil }
    // Ignore during initial sync
    if s.cfg.initialSync.Syncing() { return pubsub.ValidationIgnore, nil }
    // Reject nil topic
    if msg.Topic == nil { return pubsub.ValidationReject, p2p.ErrInvalidTopic }
    // Decode the message, reject if it fails
    m, err := s.decodePubsubMessage(msg)
    if err != nil { return pubsub.ValidationReject, err }
    // Reject wrong type
    dcsc, ok := m.(*eth.DataColumnSidecar)
    if !ok { return pubsub.ValidationReject, errWrongMessage }
    // Convert to read-only
    roDataColumn, err := blocks.NewRODataColumn(dcsc)
    if err != nil { return pubsub.ValidationReject, errors.Wrap(err, "roDataColumn conversion failure") }
    roDataColumns := []blocks.RODataColumn{roDataColumn}
    verifier := s.newColumnsVerifier(roDataColumns, verification.GossipDataColumnSidecarRequirements)
    // [REJECT] ValidFields
    if err := verifier.ValidFields(); err != nil { return pubsub.ValidationReject, err }
    // [REJECT] CorrectSubnet
    if err := verifier.CorrectSubnet(...); err != nil { return pubsub.ValidationReject, err }
    // [IGNORE] NotFromFutureSlot
    if err := verifier.NotFromFutureSlot(); err != nil { return pubsub.ValidationIgnore, err }
    // [IGNORE] SlotAboveFinalized
    if err := verifier.SlotAboveFinalized(); err != nil { return pubsub.ValidationIgnore, err }
    // [IGNORE] SidecarParentSeen
    if err := verifier.SidecarParentSeen(...); err != nil { return pubsub.ValidationIgnore, err }
    // [REJECT] SidecarParentValid
    if err := verifier.SidecarParentValid(...); err != nil { return pubsub.ValidationReject, err }
    // [REJECT] ValidProposerSignature
    if err := verifier.ValidProposerSignature(ctx); err != nil { return pubsub.ValidationReject, err }
    // [REJECT] SidecarParentSlotLower
    if err := verifier.SidecarParentSlotLower(); err != nil { return pubsub.ValidationReject, err }
    // [REJECT] SidecarDescendsFromFinalized
    if err := verifier.SidecarDescendsFromFinalized(); err != nil { return pubsub.ValidationReject, err }
    // [REJECT] SidecarInclusionProven
    if err := verifier.SidecarInclusionProven(); err != nil { return pubsub.ValidationReject, err }
    // [REJECT] KZG batch verification
    validationResult, err := s.validateWithKzgBatchVerifier(ctx, roDataColumns)
    if validationResult != pubsub.ValidationAccept { return validationResult, err }
    verifier.SatisfyRequirement(verification.RequireSidecarKzgProofVerified)
    // [IGNORE] duplicate sidecar
    if s.hasSeenDataColumnIndex(...) { return pubsub.ValidationIgnore, nil }
    // [REJECT] SidecarProposerExpected
    if err := verifier.SidecarProposerExpected(ctx); err != nil { return pubsub.ValidationReject, err }
    verifiedRODataColumns, err := verifier.VerifiedRODataColumns()
    if err != nil { return pubsub.ValidationIgnore, err }
    msg.ValidatorData = verifiedRODataColumns[0]
    return pubsub.ValidationAccept, nil
}
