// bytes.c - called from bytes_to_kzg_commitment and bytes_to_kzg_proof
static C_KZG_RET validate_kzg_g1(g1_t *out, const Bytes48 *b) {
    blst_p1_affine p1_affine;
    // Decompress the G1 element
    if (blst_p1_uncompress(&p1_affine, b->bytes) != BLST_SUCCESS)
        return C_KZG_BADARGS;
    // Accept the point at infinity
    if (blst_p1_affine_is_inf(&p1_affine))
        return C_KZG_OK;
    // Verify the point is in the G1 prime-order subgroup
    // THIS IS THE KEY SUBGROUP CHECK
    if (!blst_p1_affine_in_g1(&p1_affine))
        return C_KZG_BADARGS;
    blst_p1_from_affine(out, &p1_affine);
    return C_KZG_OK;
}
